import wollok.game.*
import dificultad.*
import personaje.*

object billetera {
    const recompensaMoneda = 10
    const apuestaMinima = 50
    var saldo = 100

    method tieneAlMenos(monto) = saldo >= monto

    method saldo() = saldo

    method sumar(monto) {
        saldo = saldo + monto
    }

    method restar(monto) {
        saldo = (saldo - monto).max(0)
    }

    method cobrarDanioCarta(monto) {
        self.restar(monto)
    }

    method recogerMoneda() {
        self.sumar(recompensaMoneda)
    }

    method puedeApostar(monto) = saldo >= monto

    method necesitaMoneda() = saldo < apuestaMinima

    method completarApuestaMinima() {
        saldo = saldo.max(apuestaMinima)
    }

    method meta(){}

    method alcanzoLaMeta() = saldo >= dificultad.actual().meta()

    method estaEnQuiebra() = saldo == 0

    method reiniciar() {
        saldo = dificultad.actual().saldoInicial()
    }
}

object marcadorFondo {
    method position() = game.at(0, 11)

    method image() = "casino/marcador-fondo.png"
}

object marcador {
    method position() = game.at(1, 11)

    method text() = billetera.saldo().toString()

    method textColor() = "FFD700"
}

// moneda que aparece en la plaza cuando Robert tiene menos de la apuesta mínima
object monedaFuente {
    const lugares = [game.at(5, 2), game.at(5, 3), game.at(5, 4), game.at(9, 2), game.at(9, 3), game.at(9, 4), game.at(6, 5), game.at(7, 5), game.at(8, 5), game.at(6, 1), game.at(7, 1), game.at(8, 1)]
    var property position = game.at(5, 3)

    method image() = "casino/moneda-fuente.png"

    method aparecer() {
        position = lugares.anyOne()
        game.addVisual(self)
    }

    method retirar() {
        game.removeVisual(self)
    }
}

object encuentroMonedaFuente {
    method activaEn(pos) = game.hasVisual(monedaFuente) and pos == monedaFuente.position()

    method usar() {
        billetera.completarApuestaMinima()
        monedaFuente.retirar()
    }
}

import wollok.game.*
import billetera.*
import juego.*
import personaje.*

class ObjetoLluvia {
    var property position = game.origin()
    var columna = 0
    var fila = 0
    var activo = false

    method image()
    method estaActivo() = activo

    method aparecerEn(unaColumna, unaFila) {
        columna = unaColumna
        fila = unaFila
        activo = true
        self.actualizarPosicion()
        game.addVisual(self)
        self.iniciar()
    }

    method iniciar() {}

    method avanzar()

    method interactuar()

    method coincideConPersonaje() = personaje.position() == position

    method actualizarPosicion() {
        self.position(game.at(columna, fila))
    }

    method chocarConPersonaje() {
        self.interactuar()
    }

    method esquivada() {
        self.retirar()
    }

    method retirar() {
        if (activo) {
            activo = false
            if (game.hasVisual(self)) { 
                game.removeVisual(self)
            }
        }
    }
}

class Carta inherits ObjetoLluvia {
    var movimientosAcumulados = 0
    var columnaPersonajeAlAparecer = 0
    var movimientosPersonajeAlAparecer = 0

    method danio() = 0
    method movimientosPorCasilla() = 2

    override method iniciar() {
        columnaPersonajeAlAparecer = personaje.position().x()
        movimientosPersonajeAlAparecer = personaje.cantidadMovimientos()
    }

    override method avanzar() {
        if (activo) {
            if (self.coincideConPersonaje()) {
                self.interactuar()
            } else {
                movimientosAcumulados += 1
                if (movimientosAcumulados >= self.movimientosPorCasilla()) {
                    self.bajarUnaCasilla()
                }
            }
        }
    }

    method bajarUnaCasilla() {
        movimientosAcumulados = 0
        if (fila > 0) {
            fila -= 1
            self.actualizarPosicion()
            if (self.coincideConPersonaje()) {
                self.interactuar()
            } else if (fila == 0) {
                self.esquivada()
            }
        } else {
            self.esquivada()
        }
    }

    override method esquivada() {
        if (activo) {
            self.retirar()
        }
    }

    override method interactuar() {
        if (activo) {
            billetera.cobrarDanioCarta(self.danio())
            
            personaje.recibirDanio() 
            
            juego.verificarQuiebra()
            self.retirar()
        }
    }
}

class CartaNormal inherits Carta {
    override method image() = "mini-jefe-crupier/carta-crupier-mini.png"
    override method danio() = 50
}

class CartaEspecial inherits Carta {
    override method image() = "mini-jefe-crupier/carta-super-crupier-mini.png"
    override method danio() = 100
    override method movimientosPorCasilla() = 1
}


class CartaRapida inherits CartaNormal {
    override method image() = "mini-jefe-crupier/carta-crupier-rapida.png"
    override method danio() = 75
    override method movimientosPorCasilla() = 1
}

class Moneda inherits ObjetoLluvia {
    override method image() = "casino/premio-vaso.png"

    override method iniciar() {
        game.schedule(8000, { self.retirar() })
    }

    override method avanzar() {
        if (activo && self.coincideConPersonaje()) {
            self.interactuar()
        }
    }

    override method interactuar() {
        if (activo) {
            billetera.recogerMoneda()
            self.retirar()
        }
    }
}

import wollok.game.*
import billetera.*
import personaje.*
import juego.*
import escenarios.*
import vasos.*
import dificultad.*

// tipos de apuestas
class Apuesta {
    method gana(resultado)
    method multiplicador()
    method nombre()
}

class ApuestaNumero inherits Apuesta {
    const numero

    override method gana(resultado) = resultado == numero
    override method multiplicador() = dificultad.actual().multiplicadorNumero()
    override method nombre() = "al número " + numero
}

object apuestaPar inherits Apuesta {
    override method gana(resultado) = resultado % 2 == 0
    override method multiplicador() = dificultad.actual().multiplicadorRango()
    override method nombre() = "a que salga par"
}

object apuestaImpar inherits Apuesta {
    override method gana(resultado) = resultado % 2 == 1
    override method multiplicador() = dificultad.actual().multiplicadorRango()
    override method nombre() = "a que salga impar"
}

object apuestaMayorA3 inherits Apuesta {
    override method gana(resultado) = resultado > 3
    override method multiplicador() = dificultad.actual().multiplicadorRango()
    override method nombre() = "a mayor que 3"
}

object apuestaMenorOIgualA3 inherits Apuesta {
    override method gana(resultado) = resultado <= 3
    override method multiplicador() = dificultad.actual().multiplicadorRango()
    override method nombre() = "a menor o igual a 3"
}

// visuales
object panelDado {
    method position() = game.at(3, 4)

    method image() = "casino/panel-vasos.png"
}

object dadoVisual {
    var property valor = 1

    method position() = game.at(7, 5)

    method image() = "casino/dado-" + valor + ".png"
}

// renglón de arriba: títulos y resultados
object mensajeDado {
    var property text = ""

    method position() = game.at(7, 7)

    method textColor() = "FFD700"
}

// renglon de abajo: opciones para elegir
object opcionesDado {
    var property text = ""

    method position() = game.at(7, 4)

    method textColor() = "FFFFFF"
}

// fases
object faseDadoLibre inherits Fase {
    override method interactuar() {
        [juegoDado].filter({ j => j.estaCerca() }).forEach({ j => j.mostrarApuestas() })
    }
}

object faseDadoMonto inherits Fase {
    override method interactuar() {
        juegoDado.cerrar()
    }

    override method numero(n) {
        juegoDado.elegirMonto(n)
    }
}

object faseDadoTipo inherits Fase {
    override method interactuar() {
        juegoDado.cerrar()
    }

    override method numero(n) {
        juegoDado.elegirTipo(n)
    }
}

object faseDadoNumero inherits Fase {
    override method interactuar() {
        juegoDado.cerrar()
    }

    override method numero(n) {
        juegoDado.elegirNumero(n)
    }
}

object faseDadoTirando inherits Fase {}

// juego de los dados
object juegoDado {
    const montos = [50, 100, 200]
    const tiposFijos = [apuestaPar, apuestaImpar, apuestaMayorA3, apuestaMenorOIgualA3]
    const caras = [1, 2, 3, 4, 5, 6]
    const celdasMesa = [game.at(6, 3), game.at(7, 3), game.at(8, 3), game.at(9, 3), game.at(6, 7), game.at(7, 7), game.at(8, 7), game.at(9, 7)]
    const cantidadTics = 14
    const tiempoTic = 120
    var fase = faseDadoLibre
    var inversion = 0
    var apuesta = apuestaPar

    method interactuar() {
        fase.interactuar()
    }

    method numero(n) {
        fase.numero(n)
    }

    method estaCerca() = personaje.estaLibre() and juego.estaEn(escenarioDados) and celdasMesa.contains(personaje.position())

    method mostrarApuestas() {
        personaje.bloquear()
        game.addVisual(panelDado)
        game.addVisual(dadoVisual)
        game.addVisual(mensajeDado)
        game.addVisual(opcionesDado)
        mensajeDado.text("¿Cuánto apostás? (E cancelar)")
        opcionesDado.text("1 - $50     2 - $100     3 - $200")
        fase = faseDadoMonto
    }

    method elegirMonto(n) {
        [n].filter({ k => k <= montos.size() }).forEach({ k => self.fijarMonto(montos.get(k - 1)) })
    }

    method fijarMonto(monto) {
        const alcanza = billetera.puedeApostar(monto)
        [monto].filter({ m => alcanza }).forEach({ m => self.pedirTipo(m) })
        [monto].filter({ m => not alcanza }).forEach({ m => mensajeDado.text("No te alcanza el saldo para apostar $" + m) })
    }

    method pedirTipo(monto) {
        inversion = monto
        fase = faseDadoTipo
        mensajeDado.text("¿A qué apostás? (E cancela)")
        opcionesDado.text("1 - Número   2 - Par   3 - Impar   4 - Mayor a 3   5 - Menor o igual a 3")
    }

    method elegirTipo(n) {
        [n].filter({ k => k == 1 }).forEach({ k => self.pedirNumero() })
        [n].filter({ k => k > 1 and k <= 5 }).forEach({ k => self.tirar(tiposFijos.get(k - 2)) })
    }

    method pedirNumero() {
        fase = faseDadoNumero
        mensajeDado.text("¿a que numero? (pulsa E para cancelar)")
        opcionesDado.text("1  -  2  -  3  -  4  -  5  -  6")
    }

    method elegirNumero(n) {
        self.tirar(new ApuestaNumero(numero = n))
    }

    method tirar(unaApuesta) {
        apuesta = unaApuesta
        fase = faseDadoTirando
        opcionesDado.text("")
        mensajeDado.text("Apostaste $" + inversion + " " + unaApuesta.nombre() + ". ¡Tirando!")
        const resultado = caras.anyOne()
        (1..cantidadTics).forEach({ i => game.schedule(i * tiempoTic, { dadoVisual.valor(caras.anyOne()) }) })
        game.schedule((cantidadTics + 1) * tiempoTic, { self.mostrarResultado(resultado) })
    }

    method mostrarResultado(resultado) {
        dadoVisual.valor(resultado)
        [resultado].filter({ r => apuesta.gana(r) }).forEach({ r => self.ganar(r) })
        [resultado].filter({ r => not apuesta.gana(r) }).forEach({ r => self.perder(r) })
        game.schedule(2500, { self.cerrar() })
    }

    method ganar(resultado) {
        const ganancia = inversion * apuesta.multiplicador()
        billetera.sumar(ganancia)
        mensajeDado.text("Salió " + resultado + ". ¡Ganaste! +$" + ganancia)
    }

    method perder(resultado) {
        billetera.restar(inversion)
        mensajeDado.text("Salió " + resultado + ". Perdiste -$" + inversion)
    }

    method cerrar() {
        game.removeVisual(opcionesDado)
        game.removeVisual(mensajeDado)
        game.removeVisual(dadoVisual)
        game.removeVisual(panelDado)
        dadoVisual.valor(1)
        fase = faseDadoLibre
        personaje.liberar()
        juego.verificarQuiebra()
    }
}

import wollok.game.*
import obstaculos.*
import juego.*
import miniJefe.*
import personaje.*
import lluviadecartas.*
import billetera.*
import musica.*
import dificultad.*
import npc.*



object fondo {
    var property image = "casino/casino-tablero.png"

    method position() = game.origin()
}

// ---------- clase madre de todos los mapas ----------
class Escenario {
    method imagen()
    method cancion()
    method salidas()
    method cargarObstaculos()

    method alCargar() {}

    method puedeCargar() = true

    method cargar() {
        [self].filter({ e => e.puedeCargar() }).forEach({ e => e.prepararMapa() })
    }

    method prepararMapa() {
        musica.cambiarA(self.cancion())
        fondo.image(self.imagen())
        obstaculos.limpiar()
        self.cargarObstaculos()
        self.alCargar()
    }
}

// ---------- casino ----------
object escenarioCasino inherits Escenario {
    override method imagen() = "casino/casino-tablero.png"
    override method cancion() = "sonidos/Casino-game-ambiente1.mp3"
    override method salidas() = [salidaCasinoAVasos, encuentroMiniJefe, salidaCasinoADados, salidaCasinoAPlaza]

    override method cargarObstaculos() {
        self.cargarCrupier()
        self.cargarParedes()
        self.cargarMesas()
        self.cargarMaquinitas()
    }

    override method alCargar() {
        [miniJefe].filter({ m => not game.hasVisual(m) }).forEach({ m => game.addVisual(m) })
    }

    method cargarParedes() {
        obstaculos.bloquearZona(0, 15, 10, 11)    // pared y cortinas de arriba
        obstaculos.bloquearZona(0, 5, 0, 1)       // abajo a la izquierda (máquinas y cordón)
        obstaculos.bloquearZona(10, 15, 0, 1)     // abajo a la derecha (cordón y máquinas)
    }

    method cargarMesas() {
        obstaculos.bloquearZona(0, 3, 8, 9)       // mesa de arriba, izquierda
        obstaculos.bloquearZona(5, 7, 8, 9)       // semicírculo izquierdo
        obstaculos.bloquearZona(8, 10, 8, 9)      // semicírculo derecho
        obstaculos.bloquearZona(12, 15, 8, 9)     // ruleta de arriba
        obstaculos.bloquearZona(0, 3, 5, 6)       // mesa del medio, izquierda
        obstaculos.bloquearZona(12, 15, 5, 6)     // ruleta del medio
    }

    method cargarMaquinitas() {
        obstaculos.bloquearZona(0, 4, 3, 4)       // maquinitas de arriba, izquierda
        obstaculos.bloquearZona(11, 15, 3, 4)     // maquinitas de arriba, derecha
    }

    method cargarCrupier() {
        const base = miniJefe.position()
        obstaculos.bloquearZona(base.x(), base.x() + 1, base.y(), base.y() + 2)    // ocupa 2 casillas de ancho y 3 de alto, como su sprite
    }
}


object salidaCasinoAVasos {
    const celdas = [game.at(15, 2)]

    method activaEn(pos) = celdas.contains(pos)

    method usar() {
        juego.irA(escenarioVasos, game.at(1, 5))
    }
}

object salidaVasosACasino {
    const celdas = [game.at(0, 4), game.at(0, 5), game.at(0, 6)]

    method activaEn(pos) = celdas.contains(pos)

    method usar() {
        juego.irA(escenarioCasino, game.at(14, 2))
    }
}

// ---------- mesa de los vasos ----------
object escenarioVasos inherits Escenario {
    override method imagen() = "casino/escenario-vasos.png"
    override method cancion() = "sonidos/vasos.mp3"
    override method salidas() = [salidaVasosACasino, encuentroNpcVasos]

    override method cargarObstaculos() {
        self.cargarParedes()
        self.cargarEscenario()
        self.cargarMesas()
        self.cargarBarra()
        self.cargarNpc()
    }

    override method alCargar() {
        [npcVasos].filter({ n => not game.hasVisual(n) }).forEach({ n => game.addVisual(n) })
    }

    method cargarParedes() {
        obstaculos.bloquearZona(0, 15, 10, 11)  // pared de arriba
        obstaculos.bloquearZona(0, 0, 9, 9)      // plantas de arriba
        obstaculos.bloquearZona(3, 3, 9, 9)
        obstaculos.bloquearZona(12, 12, 9, 9)
        obstaculos.bloquearZona(15, 15, 9, 9)
        obstaculos.bloquearZona(0, 0, 7, 7)       // planta de la izquierda
        obstaculos.bloquearZona(15, 15, 6, 7)    // planta de la derecha
        obstaculos.bloquearZona(1, 2, 6, 6)       // cordón de arriba de la puerta
        obstaculos.bloquearZona(1, 3, 3, 3)       // cordón de abajo de la puerta
    }

    method cargarEscenario() {
        obstaculos.bloquearZona(5, 10, 6, 9)      // escenario con la mesa de vasos y las banquetas del frente
        obstaculos.bloquearZona(11, 11, 7, 9)     // borde derecho del escenario y banquetas de ese lado
        obstaculos.bloquearZona(4, 4, 8, 9)       // banquetas de la izquierda del escenario
    }

    method cargarMesas() {
        obstaculos.bloquearZona(12, 15, 4, 5)   // mesa redonda de la derecha
        obstaculos.bloquearZona(5, 7, 2, 3)      // mesa redonda del medio
        obstaculos.bloquearZona(0, 2, 0, 1)   // mesa de abajo, izquierda
        obstaculos.bloquearZona(4, 6, 0, 1)   // mesa de abajo, medio
    }

    method cargarBarra() {
        obstaculos.bloquearZona(11, 15, 0, 3)   // barra y estantes
        obstaculos.bloquearZona(10, 10, 1, 2)  // banquetas de la barra
    }

    method cargarNpc() {
        obstaculos.bloquearZona(13, 14, 7, 9)     // hitbox del NPC: su cuerpo y la fila de abajo, para que Robert no se le superponga
    }
}

// ---------- sala del jefe ----------
// al tocar al crupier se pasa a este mapa y no se puede salir: la única forma es derrotarlo
// esquivando todas sus cartas, y se sale con más o menos plata que al inicio.
object escenarioPelea inherits Escenario {
    override method imagen() = "casino/salon-casino-batalla.png"
    override method cancion() = "sonidos/jefe-final.mp3"
    override method salidas() = []

    override method puedeCargar() = not lluviaDeCartas.estaJugando()

    override method cargarObstaculos() {
        obstaculos.bloquearZona(4, 11, 8, 11)
        self.cargarParedes()
        self.cargarMesas()
        self.cargarPlantas()
    }

    override method alCargar() {
        miniJefe.position(game.at(6, 8))
        [miniJefe].filter({ m => not game.hasVisual(m) }).forEach({ m => game.addVisual(m) })
        lluviaDeCartas.iniciar()
    }

    method cargarParedes() {
        obstaculos.bloquearZona(0, 15, 10, 11)    // pared de arriba y escenario del fondo
        obstaculos.bloquearZona(0, 0, 0, 9)       // pared izquierda
        obstaculos.bloquearZona(15, 15, 0, 9)     // pared derecha
        obstaculos.bloquearZona(1, 6, 0, 1)       // pared de abajo, a la izquierda de la alfombra
        obstaculos.bloquearZona(9, 14, 0, 1)      // pared de abajo, a la derecha de la alfombra
    }

    method cargarMesas() {
        obstaculos.bloquearZona(1, 3, 7, 8)       // mesa de arriba, izquierda (con banquetas)
        obstaculos.bloquearZona(12, 14, 7, 8)     // mesa de arriba, derecha (con banquetas)
        obstaculos.bloquearZona(1, 4, 4, 5)       // ruleta de la izquierda
        obstaculos.bloquearZona(2, 4, 3, 3)       // banquetas de la ruleta izquierda
        obstaculos.bloquearZona(11, 14, 4, 5)     // ruleta de la derecha
        obstaculos.bloquearZona(11, 13, 3, 3)     // banquetas de la ruleta derecha
    }

    method cargarPlantas() {
        obstaculos.bloquearZona(4, 4, 9, 9)       // planta de arriba, izquierda
        obstaculos.bloquearZona(11, 11, 9, 9)     // planta de arriba, derecha
        obstaculos.bloquearZona(1, 1, 2, 2)       // planta de abajo, izquierda
        obstaculos.bloquearZona(14, 14, 2, 2)     // planta de abajo, derecha
    }
}

// ---------- mesa de dados ----------
object escenarioDados inherits Escenario {
    override method imagen() = "casino/tablero-dados.png"
    override method cancion() = "sonidos/dados.mp3"
    override method salidas() = [salidaDadosACasino]

    override method cargarObstaculos() {
        self.cargarParedes()
        self.cargarMesa()
        self.cargarPlantas()
    }

    method cargarParedes() {
        obstaculos.bloquearZona(0, 15, 9, 11)     // pared de arriba con plantas y escenario
        obstaculos.bloquearZona(0, 15, 0, 1)      // barandas y cordones de abajo
    }

    method cargarMesa() {
        obstaculos.bloquearZona(5, 10, 4, 6)      // mesa de dados y banquetas
    }

    method cargarPlantas() {
        obstaculos.bloquearZona(0, 0, 6, 7)       // plantas de la izquierda
        obstaculos.bloquearZona(0, 1, 2, 2)       // plantas de abajo, izquierda
        obstaculos.bloquearZona(14, 15, 2, 2)     // plantas de abajo, derecha
    }
}

object salidaCasinoADados {
    const celdas = [game.at(0, 2)]

    method activaEn(pos) = celdas.contains(pos)

    method usar() {
        juego.irA(escenarioDados, game.at(14, 5))
    }
}

object salidaDadosACasino {
    const celdas = [game.at(15, 5), game.at(15, 6)]

    method activaEn(pos) = celdas.contains(pos)

    method usar() {
        juego.irA(escenarioCasino, game.at(1, 2))
    }
}

object encuentroMiniJefe {
    method activaEn(pos) =
        (pos.x() - miniJefe.position().x()).between(-1, 2) and
        (pos.y() - miniJefe.position().y()).between(-1, 3)

    method usar() {
        const puedePasar = billetera.tieneAlMenos(dificultad.actual().fichasParaElJefe())
        [self].filter({ e => puedePasar }).forEach({ e => juego.irA(escenarioPelea, game.at(7, 1)) })
        [self].filter({ e => not puedePasar }).forEach({ e => e.advertir() })
